using System;
using System.Collections.Generic;

// A curated starting guide, not an exhaustive map or drop database.
// Quest locations: https://classic.battle.net/diablo2exp/quests/
// Region connections and waypoints: https://classic.battle.net/diablo2exp/maps/
public sealed class GuideRegion {
 public int Act;
 public string Name, Points, Quests, Farming;
 public GuideRegion(int act,string name,string points,string quests,string farming){Act=act;Name=name;Points=points;Quests=quests;Farming=farming;}
 public override string ToString(){return Name;}
 public string Details(){return Name.ToUpperInvariant()+"\r\n\r\nPOINTS OF INTEREST\r\n"+Points+"\r\n\r\nQUESTS\r\n"+Quests+"\r\n\r\nFARMING TIPS\r\n"+Farming+"\r\n\r\nMaps vary between games; rewards and drops depend on difficulty and game mode.\r\n\r\nQuest and map reference: classic.battle.net/diablo2exp/quests/";}
}
public static class GuideBook {
 public static readonly GuideRegion[] Regions={
  new GuideRegion(1,"Blood Moor & Den of Evil","Find the Den entrance in the Blood Moor outside the Rogue Encampment.","Den of Evil: clear every monster inside, then speak to Akara for a skill point.","A useful early place to gain experience and find basic equipment. Use the remaining-monsters counter to find stragglers."),
  new GuideRegion(1,"Cold Plains & Burial Grounds","The Cold Plains waypoint leads toward the Burial Grounds and its crypts.","Sisters' Burial Grounds: defeat Blood Raven and return to Kashya for a Rogue mercenary.","Visit the Burial Grounds and nearby crypts for monsters and early gear; choose a difficulty your build can clear safely."),
  new GuideRegion(1,"Stony Field & Dark Wood","Find the Cairn Stones in the Stony Field and the Tree of Inifuss in the Dark Wood, through the Underground Passage.","The Search for Cain: bring the scroll to Akara, activate the stones in the indicated order, and rescue Cain in Tristram.","Tristram contains groups of monsters and unique enemies. Revisit it for early experience and items."),
  new GuideRegion(1,"Black Marsh & Forgotten Tower","Find the Forgotten Tower in the Black Marsh; the Countess is on the fifth cellar level.","The Forgotten Tower: explore the tower and defeat the Countess.","The Countess is a popular repeat target for runes. Her possible drops change with difficulty; use the Black Marsh waypoint to start a run."),
  new GuideRegion(1,"Monastery & Catacombs","Look for the Barracks, Jail, Inner Cloister and Catacombs; Andariel waits on Catacombs level 4.","Tools of the Trade: recover the Horadric Malus in the Barracks. Sisters to the Slaughter: defeat Andariel.","Andariel is a repeatable act boss for item farming. Poison resistance and antidotes help against her attacks."),
  new GuideRegion(2,"Lut Gholein Sewers","The sewers beneath Lut Gholein contain Radament on level 3.","Radament's Lair: defeat Radament and use the Book of Skill; find the Horadric Scroll nearby.","Clear the area for experience while pursuing the quest. Poison resistance can help against undead attacks."),
  new GuideRegion(2,"Halls, Maggot Lair & Viper Temple","The Halls of the Dead contain the Horadric Cube; the Maggot Lair holds the staff, and the Claw Viper Temple holds the amulet.","The Horadric Staff and Tainted Sun: collect the pieces, transmute the staff and destroy the altar.","Keep the Cube for recipes. Narrow tunnels can be awkward for summons; reposition carefully and progress patiently."),
  new GuideRegion(2,"Arcane Sanctuary & Tombs","The Palace leads to the Arcane Sanctuary. The Summoner's journal reveals the true tomb symbol.","The Summoner and The Seven Tombs: defeat the Summoner, identify the tomb and use the completed staff to reach Duriel.","The Summoner and Duriel can be revisited. Prepare for Duriel's cold aura and close-quarters fight."),
  new GuideRegion(3,"Spider Forest & Flayer Jungle","The Spider Cavern holds Khalim's Eye; the Flayer Dungeon holds his Brain. The Gidbinn is in the Flayer Jungle.","Khalim's Will: collect the relics. Blade of the Old Religion: recover the Gidbinn and return it to Ormus.","Dense groups can reward area damage, but small fast enemies can overwhelm fragile characters."),
  new GuideRegion(3,"Kurast Bazaar & Sewers","The Ruined Temple contains Lam Esen's Tome; Khalim's Heart is in the Kurast Sewers.","Lam Esen's Tome: return the book to Alkor for attribute points. Collect the Heart for Khalim's Will.","Explore the temples and sewers for monsters and chests. Pack space and a town portal make longer runs easier."),
  new GuideRegion(3,"Travincal & Durance of Hate","The High Council guards Travincal. After opening the way, the Durance leads to Mephisto on level 3.","The Blackened Temple: defeat the Council. Khalim's Will opens the Durance. The Guardian: defeat Mephisto.","The Council and Mephisto are popular repeat targets for loot. Bring fire resistance for the Council and watch for dangerous Durance monsters."),
  new GuideRegion(4,"Plains of Despair","Search the Plains of Despair for Izual.","The Fallen Angel: defeat Izual and speak to Tyrael for two skill points.","The open area has many monsters, but its layout and enemy groups vary. Finish the reward on each difficulty."),
  new GuideRegion(4,"River of Flame & Hellforge","The Hellforge and Hephasto are in the River of Flame; the river also leads toward the Chaos Sanctuary.","The Hellforge: use the Hellforge Hammer to destroy Mephisto's Soulstone.","The Hellforge quest awards gems and a rune in the expansion; the rune range depends on difficulty. This is a quest reward, not a repeatable drop per character and difficulty."),
  new GuideRegion(4,"Chaos Sanctuary","Five seals surround Diablo's sanctuary. Opening them releases dangerous seal guardians.","Terror's End: open the seals and defeat Diablo.","A popular late-game run for experience and items. Expect mixed damage types and immunities on higher difficulties."),
  new GuideRegion(5,"Bloody Foothills & Frigid Highlands","Shenk the Overseer is in the Bloody Foothills; imprisoned soldiers are in the Frigid Highlands.","Siege on Harrogath: defeat Shenk and return to Larzuk. Rescue on Mount Arreat: free the soldiers for Qual-Kehk.","Shenk and nearby Eldritch are commonly visited from the Frigid Highlands waypoint for quick monster kills."),
  new GuideRegion(5,"Frozen River & Halls of Vaught","Anya is trapped in the Frozen River. Nihlathak is in the Halls of Vaught, reached through Anya's portal after her rescue.","Prison of Ice: rescue Anya. Betrayal of Harrogath: defeat Nihlathak.","Nihlathak is a repeat target for keys in Hell difficulty. His corpse explosions can be deadly; keep distance and control corpses where possible."),
  new GuideRegion(5,"Arreat Summit & Worldstone Keep","The Ancients guard Arreat Summit; the Worldstone Keep leads to the Throne of Destruction and Baal.","Rite of Passage: defeat the Ancients. Eve of Destruction: defeat Baal. Ancients require level 20/40/60 in Normal/Nightmare/Hell for quest credit.","Baal and his waves are common experience and item targets. Prepare for varied monsters and resistances.")
 };
}
